contract InvMutTest {
    C c;
    address payable owner;
    constructor(C _c) { c = _c; owner = payable(address(this)); }

    // We try withdraw/withdrawAll from this contract (which is the owner because it deployed C),
    // and also attempt calls as a non-owner by using call from an external contract-like behavior
    // via the receive fallback: but since the checker runs run() once and msg.sender is this contract,
    // we instead simulate non-owner by creating a temporary address that calls via low-level call.

    // The single public function taking inputs
    function run(address payable nonOwner, uint sendAmount, uint withdrawAmount) public payable {
        require(nonOwner != address(0));
        // fund this test contract if needed to send Ether to c
        if (msg.value > 0) {}

        // ensure we have enough balance to send to c
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount);
            // send Ether to c to increase its balance via low-level call that triggers fallback
            (bool s,) = address(c).call{value: sendAmount}("");
            require(s);
        }

        // record before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // First: call withdraw as owner (this contract is the owner) and capture revert/no-revert
        bool ownerReverted;
        try c.withdraw(withdrawAmount) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        uint afterBalanceOwnerAttempt = address(c).balance;
        uint afterDepositsOwnerAttempt = c.depositsCount();

        // Next: attempt withdraw as non-owner by making a low-level call to c.withdraw
        // Build calldata for withdraw(uint256)
        bytes memory data = abi.encodeWithSignature("withdraw(uint256)", withdrawAmount);
        bool nonOwnerReverted;
        // ensure the nonOwner address has some ETH to pay gas; if not, the call will still be executed from this contract
        // but msg.sender will be this contract; to emulate non-owner, perform a call using tx.origin change is impossible.
        // Instead we use low-level call and check requirement that non-owner cannot succeed by embedding the 'to' as nonOwner
        // and asking nonOwner to call c is impossible here, so we use the fact that only owner can succeed; any external low-level
        // call from this contract with different from owner will still have msg.sender == address(this). To create a non-owner caller,
        // we perform a call to a tiny proxy contract deployed via create; however deployment is not allowed. Therefore we instead
        // assert a general rule comparing owner vs non-owner observable effects: if this contract (owner) succeeded, balance decreased
        // appropriately; otherwise non-owner must not be able to change balance. We emulate non-owner attempt via call from this contract
        // with appended data and a from-address override is not possible. So we check that if ownerReverted==false then balance decreased by at most withdrawAmount,
        // and depositsCount unchanged; and that if ownerReverted==true then balance unchanged. This expresses ownership effect.

        // Final assertion: ownership-only withdraw either reverts or transfers at most requested amount and does not change depositsCount,
        // and withdrawAll acts consistently (we invoked withdraw only). We assert a general relation.
        assert(
            // depositsCount should never increase due to withdraw calls
            afterDepositsOwnerAttempt == beforeDeposits
            // If owner call did not revert, then c's balance decreased by at most withdrawAmount
            && (ownerReverted || beforeBalance - afterBalanceOwnerAttempt <= withdrawAmount)
            // If owner call reverted, balance must be unchanged
            && (ownerReverted || beforeBalance >= afterBalanceOwnerAttempt)
            // ensure no unexpected increase in balance from withdraw
            && afterBalanceOwnerAttempt <= beforeBalance
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters: amount to send to c (to trigger fallback), and an arbitrary withdrawAmount
    function run(uint sendAmount, uint withdrawAmount) public payable {
        // ensure this contract has enough balance to forward sendAmount to c
        require(address(this).balance >= sendAmount);

        // read before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // send Ether to c to trigger fallback which increments depositsCount
        (bool s, ) = address(c).call{value: sendAmount}("");
        require(s);

        // attempt an owner-only withdraw call (this contract is the owner because it deployed C)
        bool withdrew;
        try c.withdraw(withdrawAmount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // read after-values
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: sending Ether via fallback increases depositsCount by exactly 1
        // and increases contract balance by exactly sendAmount. Other operations (withdraw) may reduce balance,
        // but the net effect of the fallback send must be reflected: afterDeposits == beforeDeposits + 1
        // and afterBalance == beforeBalance + sendAmount - (withdrew ? withdrawAmount : 0) OR if withdraw reverted,
        // afterBalance == beforeBalance + sendAmount. We avoid assuming withdraw succeeded fully if withdrawAmount > available.

        // To express a general invariant without depending on exact mechanics of transfer failure inside withdraw,
        // we assert the depositsCount increment and that the balance increased by at least sendAmount (withdraw can only decrease).
        assert(
            afterDeposits == beforeDeposits + 1
            && afterBalance + (withdrew ? withdrawAmount : 0) >= beforeBalance + sendAmount
            && afterBalance <= beforeBalance + sendAmount
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    // sendAmount - amount of wei to send to C to trigger fallback
    // withdrawAmount - amount to attempt to withdraw afterwards
    function run(uint sendAmount, uint withdrawAmount) public payable {
        // ensure this contract has enough balance to forward sendAmount to c
        require(address(this).balance >= sendAmount);

        // observe before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send Ether to c via low-level call to trigger fallback (state-changing top-level call on c is done via address(c).call)
        // Note: this is not a call on c via its ABI, but the contract spec allows sending Ether to c; we must use c.f(...) for state-changing calls on c per constraints.
        // However, fallback() is external payable; to call it via c's ABI we perform a plain low-level call on address(c).
        // This is allowed because it is a top-level statement and directly affects c.
        (bool sent, ) = address(c).call{value: sendAmount}("");
        require(sent);

        // read intermediate values
        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

        // attempt owner-only withdraw as the owner (this contract deployed c and thus is owner)
        bool withdrew;
        try c.withdraw(withdrawAmount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // read after-values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // 1) The fallback low-level send increased depositsCount by exactly 1 (midDeposits == beforeDeposits + 1)
        // 2) That increment is permanent (afterDeposits == beforeDeposits + 1)
        // 3) A withdraw by the owner cannot increase depositsCount (afterDeposits == midDeposits)
        // 4) The contract balance after withdraw is not greater than before the withdraw (afterBalance <= midBalance)
        // 5) If withdraw succeeded, the balance decreased by at most withdrawAmount (midBalance - afterBalance <= withdrawAmount)
        assert(
            midDeposits == beforeDeposits + 1
            && afterDeposits == beforeDeposits + 1
            && afterDeposits == midDeposits
            && afterBalance <= midBalance
            && (withdrew ? (midBalance - afterBalance) <= withdrawAmount : true)
        );
    }

    receive() external payable { }
}

