contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    // Params:
    // sendAmount: amount of wei this test will send to C via plain call to trigger fallback
    // withdrawAmount: amount to attempt to withdraw via withdraw(uint)
    // Note: msg.sender for calls to C will be this contract (the owner of C)
    function run(uint sendAmount, uint withdrawAmount) public payable {
        // Ensure this contract has enough balance to send to C
        require(address(this).balance >= sendAmount, "not enough funds to send");

        // 1) Trigger fallback by sending Ether to C (this is a top-level call)
        (bool sent, ) = address(c).call{value: sendAmount}("");
        // we don't require sent because fallback might revert; still the call is a top-level state-changing interaction

        // Observe before values
        uint depositsBefore = c.depositsCount();
        uint balanceBefore = address(c).balance;

        // 2) Attempt withdraw(uint) as top-level state-changing call, capture revert with try/catch
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Observe after withdraw
        uint depositsAfterWithdraw = c.depositsCount();
        uint balanceAfterWithdraw = address(c).balance;

        // 3) Attempt withdrawAll() as top-level state-changing call, capture revert with try/catch
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Observe after withdrawAll
        uint depositsAfterWithdrawAll = c.depositsCount();
        uint balanceAfterWithdrawAll = address(c).balance;

        // General rule (single assert):
        // - If withdraw(uint) succeeded then C.balance did not increase and depositsCount did not decrease.
        // - If withdrawAll() succeeded then C.balance did not increase and depositsCount did not decrease (compared to before any withdrawals).
        assert(
            (withdrawReverted || (balanceAfterWithdraw <= balanceBefore && depositsAfterWithdraw >= depositsBefore))
            &&
            (withdrawAllReverted || (balanceAfterWithdrawAll <= balanceBefore && depositsAfterWithdrawAll >= depositsBefore))
        );
    }
}

contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = address(this); }

    // Try to withdraw from c as either owner (this contract) or as an external attacker by sending a call from a different address
    // We cannot change msg.sender when calling c from here, so to simulate a non-owner we use c.sendMoney to send Ether out to a target and then
    // assert properties about withdraw behavior using the public getters and revert detection.
    // We'll take as inputs: whether to attempt withdrawAll (bool useAll), an amount to withdraw, and an amount of Ether to fund c with via fallback.
    function run(bool useAll, uint fundAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Ensure c has some Ether by calling its fallback: send Ether directly to contract address via call to c with value.
        // The fallback increments depositsCount.
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent);

        // Read observables before the potentially-reverting call
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Now attempt to withdrawValue as this contract (which is the owner recorded in c at deploy time)
        bool withdrewReverted;
        if (useAll) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }

        // Observables after the call
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: since this contract was the deployer of C, it is the owner and therefore any withdraw or withdrawAll call it makes must NOT revert,
        // and must not change depositsCount (fallback only changes it), and the contract balance must be reduced by at most the requested amount (or to zero for withdrawAll).
        // We express that: withdrewReverted == false, depositsCount unchanged, and afterBalance <= beforeBalance, and if withdrawAll then afterBalance==0 else afterBalance + (withdrewReverted ? 0 : withdrawAmount) == beforeBalance || (withdrewReverted && afterBalance==beforeBalance)

        if (useAll) {
            // For withdrawAll: should not revert, depositsCount unchanged, and afterBalance == 0
            assert(withdrewReverted == false && afterDeposits == beforeDeposits && afterBalance == 0);
        } else {
            // For withdraw(amount): should not revert, depositsCount unchanged, and beforeBalance >= withdrawAmount and afterBalance == beforeBalance - withdrawAmount
            // Note: transfer may revert if not enough balance; but according to contract logic owner can withdraw any _value via transfer which will revert if insufficient funds.
            // Because this contract is owner, the call should succeed only when beforeBalance >= withdrawAmount. We assert the equivalence:
            bool succeeded = (withdrewReverted == false);
            bool enough = (beforeBalance >= withdrawAmount);
            assert(succeeded == enough && afterDeposits == beforeDeposits && (succeeded ? afterBalance == beforeBalance - withdrawAmount : afterBalance == beforeBalance));
        }
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs: useAll determines whether to call withdrawAll or withdraw(amount).
    // fundAmount is forwarded to C's fallback to fund it prior to withdraw.
    function run(bool useAll, uint fundAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Fund C by invoking its fallback which increments depositsCount.
        (bool sentFund, ) = address(c).call{value: fundAmount}("");
        require(sentFund);

        // Read observables before the withdraw call
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Perform the state-changing call as top-level statements
        bool callReverted;
        if (useAll) {
            try c.withdrawAll() {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        }

        // Read observables after the call
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Single assert expressing the general rule described above
        assert(
            // depositsCount must be unchanged by withdraw/withdrawAll
            afterDeposits == beforeDeposits
            // If withdrawAll was called: it must not revert and must drain balance to 0
            && (useAll ? (callReverted == false && afterBalance == 0) 
                // If withdraw(amount) was called: it succeeds iff beforeBalance >= withdrawAmount,
                // and when it succeeds it reduces balance by withdrawAmount; if it reverts balance unchanged.
                : ((callReverted == false) == (beforeBalance < withdrawAmount ? false : true))
