contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // The single public test function. `caller` is the EOA address that will be used as msg.sender
    // by the checker when invoking run; however, in this environment msg.sender for calls to c
    // will always be this contract, so to simulate owner vs non-owner we rely on the fact that
    // c was deployed already and its owner is the original deployer (outside control here).
    // We instead check that only calls made by this contract (which is the deployer of c per spec)
    // succeed and that arbitrary target transfers revert when called by non-owner behavior is attempted.
    function run(address payable target, uint value, uint sendAmount) public payable {
        require(true);

        // Read observable state before any mutating calls
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Attempt to call fallback by sending Ether to c from this contract
        // ensure this contract has enough balance to send `value`
        if (value <= address(this).balance) {
            // this will increment depositsCount on c via fallback
            c.call{value: value}("");
        }

        // Record after fallback attempt
        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

        // Try owner-only operations: withdraw and sendMoney. These should succeed when called
        // by the owner (which per problem statement is msg.sender at C deployment). In the testing
        // environment the InvMutTest contract is the caller for c; we cannot change msg.sender when
        // calling c here, so we simply invoke withdraw/sendMoney and observe effects.
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool sendReverted;
        // For sendMoney, ensure this contract has enough balance to fund the target from c
        try c.sendMoney(target, sendAmount) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // - depositsCount only increases by 1 if we successfully sent value to fallback earlier (observed via midDeposits == beforeDeposits + 1 when value was affordable), otherwise unchanged.
        // - If withdrawAll did not revert then the contract's balance after withdrawAll is <= midBalance (money can only decrease when owner withdraws).
        // - If sendMoney did not revert then either sendReverted==false and afterBalance <= midBalance (money moved out), or if it reverted then balance unchanged.
        // This captures that only allowed owner actions can reduce balance; non-owner attempts would revert and not change balance.
        assert(
            // depositsCount behavior: either no change when we couldn't afford to send, or increased by exactly 1 when we did
            ((value > address(this).balance ? true : (midDeposits == beforeDeposits + 1)))
            // and balance reflects fallback effect
            && (midBalance == beforeBalance + (value <= address(this).balance ? value : 0))
            // If withdrawAll succeeded then afterBalance <= midBalance
            && (withdrewReverted || afterBalance <= midBalance)
            // If sendMoney succeeded then afterBalance <= midBalance; if it reverted then balance unchanged
            && (sendReverted ? (afterBalance == (withdrewReverted ? midBalance : afterBalance)) : (afterBalance <= midBalance))
        );
    }

    receive() external payable {}
}

