        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Call fallback by sending Ether to c using its address
        if (value > 0) {
            // transfer via low-level call on address(c)
            (bool sent, ) = address(c).call{value: value}("");
            // we don't require success here: fallback payable should accept the funds unless it reverts
            // but if it reverts then sent == false and no state change occurs
        }

        // Record after fallback attempt
        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

        // Attempt withdrawAll and record whether it reverted
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Attempt sendMoney and record whether it reverted
        bool sendReverted;
        try c.sendMoney(target, sendAmount) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Assert the general rule:
        // 1) If we successfully sent `value` to C (i.e., value>0 and midBalance == beforeBalance + value) then depositsCount increased by exactly 1.
        //    Otherwise depositsCount did not increase.
        // 2) Neither withdrawAll nor sendMoney can increase C's balance. If they succeed (didn't revert) then afterBalance <= midBalance.
        // 3) If both owner actions reverted, balance remains equal to midBalance (they made no change).
        assert(
            (
                // Case: we intended to send value
                (value > 0
                    ? (midBalance == beforeBalance + value && midDeposits == beforeDeposits + 1)
                    : (midBalance == beforeBalance && midDeposits == beforeDeposits)
                )
            )
            &&
