contract InvMutTest {
    C c;
    address other;

    constructor(C _c) { c = _c; other = address(0x100); }

    // We accept inputs: whether to call withdraw, withdrawAll, sendMoney, or trigger fallback by sending Ether;
    // and an amount for calls that send Ether to or from the contract.
    function run(uint8 action, address target, uint amount) public payable {
        require(action <= 3);
        // Ensure this contract has enough balance to send amount when needed
        if (action == 3 || action == 2) {
            require(address(this).balance >= amount);
        }

        // Read before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        bool reverted = false;
        // action: 0 = withdraw(amount), 1 = withdrawAll(), 2 = sendMoney(target, amount), 3 = fallback via sending Ether
        if (action == 0) {
            // try withdraw(amount)
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 1) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 2) {
            // sendMoney to target
            try c.sendMoney(target, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 3) {
            // trigger fallback by sending Ether from this contract to c
            // note: c.fallback increments depositsCount on payable fallback
            // perform low-level call to send Ether
            (bool ok, ) = address(c).call{value: amount}("");
            reverted = !ok;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: because the InvMutTest contract deployed c, it is the owner; therefore any successful call (not reverted)
        // that withdraws or sendMoney must decrease c.balance appropriately; non-owner callers would revert and not change balance.
        // We encode: if the action call did not revert, then the change in c.balance is consistent with the action semantics;
        // if it reverted, depositsCount and balance must remain unchanged.

        // For withdraw(amount): non-reverting implies c.balance decreased by exactly amount (or to 0 if amount>beforeBal and transfer would revert — but transfer will revert instead)
        // For withdrawAll(): non-reverting implies c.balance decreased to 0.
        // For sendMoney(target, amount): non-reverting implies c.balance decreased by amount.
        // For fallback (action==3): non-reverting implies depositsCount increased by 1 and c.balance increased by amount.

        if (action == 0) {
            if (!reverted) {
                assert(afterBal + amount == beforeBal);
            } else {
                assert(afterBal == beforeBal && afterDeposits == beforeDeposits);
            }
        } else if (action == 1) {
            if (!reverted) {
                assert(afterBal == 0);
            } else {
                assert(afterBal == beforeBal && afterDeposits == beforeDeposits);
            }
        } else if (action == 2) {
            if (!reverted) {
                assert(afterBal + amount == beforeBal);
            } else {
                assert(afterBal == beforeBal && afterDeposits == beforeDeposits);
            }
        } else {
            // fallback
            if (!reverted) {
                assert(afterDeposits == beforeDeposits + 1);
                assert(afterBal == beforeBal + amount);
            } else {
                assert(afterBal == beforeBal && afterDeposits == beforeDeposits);
            }
        }
    }

    receive() external payable {}
}

