contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = address(this); }

    // The test takes an address `caller` that will attempt privileged actions by making
    // calls from this test contract but simulating different callers is not possible here.
    // Instead we rely on the fact that the checker deploys a fresh C with owner = msg.sender
    // where msg.sender was the account that deployed C; in this harness, the test can
    // check behavior when it (the owner) calls and when a non-owner call is attempted
    // via c.sendMoney to an attacker contract which will itself call c. For simplicity
    // we instead check that a withdraw attempt from a non-owner (simulated by invoking
    // a low-level call to c from a newly created minimal attacker contract) must revert
    // and leave balances and depositsCount unchanged.

    // Single public test function as required. amount is used for sending Ether to c
    // and to attempt withdrawals. attackerCodeSalt allows distinct attacker deployments.
    function run(uint amount, uint attackerCodeSalt) public payable {
        require(true);

        // Fund this test contract if needed (checker ensures it has Ether for calls)
        // Deposit Ether into c via fallback by sending value from the owner (this contract)
        // Ensure we have enough balance to fund the deposit call
        if (amount > 0) {
            require(address(this).balance >= amount, "insufficient balance for deposit");
            // send Ether to c to increase address(c).balance and increment depositsCount
            c.fallback{value: amount}();
        }

        // Record before-values observable from c
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Deploy a minimal attacker contract using create2-like uniqueness via assembly and salt
        // The attacker will try to call withdraw on c (which should revert because attacker != owner)
        address attacker;
        {
            bytes memory code = abi.encodePacked(
                // constructor: code copies runtime code and returns it
                hex"600a80600b600039600a6000f3",
                // runtime: push4 selector, push1 0, push1 0, call (will forward all gas and no value), then revert on failure
                // but we need the attacker to call c.withdraw(uint256) with value 0
                // we'll write runtime that performs a call to c with selector of withdraw(uint256)
                hex"6080604052348015600f57600080fd5b5060a68061001e6000396000f3fe",
                // Append data for runtime that calls target contract at known address slot
                hex""
            );
            // For simplicity and to avoid complex bytecode, deploy a trivial contract that attempts to call withdraw(0)
            bytes memory simple = type(SimpleAttacker).creationCode;
            // include constructor arg: target address
            bytes memory init = abi.encodePacked(simple, abi.encode(address(c)));
            assembly {
                attacker := create(0, add(init, 0x20), mload(init))
            }
        }

        // If attacker deploy failed, we cannot proceed with non-owner call; in that case assert will be vacuously true only if owner behavior holds.
        bool attackerDeployed = (attacker != address(0));

        // Attempt call from attacker to withdraw 1 wei (should revert because onlyOwner)
        bool attackerReverted = true;
        if (attackerDeployed) {
            // call the attacker's function that in turn calls c.withdraw(1)
            (bool ok, ) = attacker.call(abi.encodeWithSignature("attackWithdraw(uint256)", 1));
            attackerReverted = !ok;
        }

        // Now owner (this contract) attempts withdrawAll which should succeed and reduce c balance to 0
        bool ownerReverted = false;
        uint ownerBalanceBefore = address(this).balance;
        try c.withdrawAll() {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }
        uint ownerBalanceAfter = address(this).balance;
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule to assert:
        // 1) If attacker was deployed then its attempted withdraw must revert (non-owner can't withdraw) and c's balance and depositsCount remain unchanged by that attempt.
        // 2) After the owner calls withdrawAll, either it reverted (then balances/deposits unchanged), or it succeeded and c.balance decreased by at most the amount beforeBalance and owner balance increased accordingly.
        // We express a single combined assertion covering the invariants.
        assert(
            (
                // If attacker exists then its call reverted and did not change c state
                (!attackerDeployed) || (attackerReverted && address(c).balance == beforeBalance && c.depositsCount() == beforeDeposits)
            )
            &&
            (
                // Owner withdrawAll either reverted (no state change) or succeeded and emptied contract balance
                (ownerReverted && address(c).balance == beforeBalance && c.depositsCount() == beforeDeposits)
                ||
                (!ownerReverted && afterBalance == 0 && c.depositsCount() == beforeDeposits)
            )
        );
    }

    // Minimal attacker contract used via creation code above
    // It stores target c address on construction and exposes attackWithdraw(uint) to call c.withdraw
    receive() external payable {}
}

contract SimpleAttacker {
    address target;
    constructor(address _t) payable { target = _t; }
    function attackWithdraw(uint v) public returns (bool) {
        // try to call withdraw on target; expect revert since not owner
        (bool ok, ) = target.call(abi.encodeWithSignature("withdraw(uint256)", v));
        require(ok);
        return ok;
    }
}

contract InvMutTest {
