    // Single public entry as required. amount funds the contract C via a payable low-level call to its fallback.
    // We also take an attackerDeploymentFlag to decide whether to deploy a simple attacker contract that will try to call withdraw.
    function run(uint amount, uint attackerDeploymentFlag) public payable {
        require(amount == amount); // no-op to satisfy template style; keep function using params

        // If we will send Ether to c, ensure this test contract has enough balance
        if (amount > 0) {
