            bytes memory bytecode = type(SimpleAttacker).creationCode;
            bytes memory init = abi.encodePacked(bytecode, abi.encode(address(c)));
            assembly {
                attacker := create(0, add(init, 0x20), mload(init))
            }
        }

        bool attackerDeployed = (attacker != address(0));

        // If attacker deployed, let it attempt to call withdraw(1). Capture whether the call reverted (ok==false)
        bool attackerReverted = true;
        if (attackerDeployed) {
            (bool ok, ) = attacker.call(abi.encodeWithSignature("attackWithdraw(uint256)", 1));
            attackerReverted = !ok;
        }

        // Now, this contract (which is the owner of c because c was deployed with msg.sender = this test deployer)
        // attempts to call withdrawAll. Catch whether it reverted.
        bool ownerReverted = false;
        try c.withdrawAll() {
