        } catch {
            ownerReverted = true;
        }

        // Observables after actions
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Assertion (single general rule):
        // - If an attacker was deployed then its attempt must revert and it must not have changed C's balance or depositsCount.
        // - The owner withdrawAll either reverted (in which case C's balance/deposits unchanged) or succeeded and emptied C's balance (afterBalance == 0) while depositsCount remains unchanged.
        assert(
            (
                (!attackerDeployed) || (attackerReverted && address(c).balance == beforeBalance && c.depositsCount() == beforeDeposits)
            )
            &&
            (
                (ownerReverted && address(c).balance == beforeBalance && c.depositsCount() == beforeDeposits)
                ||
                (!ownerReverted && afterBalance == 0 && c.depositsCount() == beforeDeposits)
            )
        );
    }

    // Minimal attacker contract used above
    receive() external payable {}
}

// Needed auxiliary contract type used only for creationCode; it's allowed because it's in the same compilation unit
contract SimpleAttacker {
    address target;
    constructor(address _t) payable { target = _t; }
    // This function attempts to call c.withdraw(uint) on the target. It returns false if the low-level call failed.
    function attackWithdraw(uint v) public returns (bool) {
        (bool ok, ) = target.call(abi.encodeWithSignature("withdraw(uint256)", v));
        // propagate success as true, but revert if the call succeeded (we expect failure for non-owner) to make behavior observable by the caller
        // To keep a simple observable, require ok so that the external call returns false (reverted) when the attack fails.
        require(ok);
        return ok;
    }
}

