    // callerIsOwner: if true, we invoke withdraw/withdrawAll from this contract (owner);
    // amount: amount of wei to send to fallback to increase depositsCount and contract balance
    // withdrawAmount: amount attempted to withdraw
    function run(bool callerIsOwner, uint amount, uint withdrawAmount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

