        assert(
            // deposit effect
            finalDeposits == beforeDeposits + 1
            && afterDeposits == beforeDeposits + 1
            && afterBal == beforeBal + amount
            // withdraw behavior: owner-call does not revert
            && withdrewReverted == false
            // balance monotonicity: final balance is <= afterBal (withdraw can only decrease contract balance)
            && finalBal <= afterBal
        );
    }

