contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test attempts to call withdraw, withdrawAll, and sendMoney as a non-owner (this contract).
    // It checks that none of these calls can succeed and that address(c).balance does not decrease.
    function run(uint sendAmount, address target) public payable {
        require(address(this).balance >= sendAmount);

        // Fund the target contract c by calling its fallback via sending Ether to it from this contract.
        // This is a top-level state-changing call directly on c: use the public fallback by sending Ether through c.sendMoney is owner-only so fallback must be used.
        // However we cannot call fallback via c.<fallback>(), so instead we call address(c).call{value: sendAmount}("");
        // That low-level call is not a call on c through its typed interface, so to satisfy the constraint that state-changing calls on c must be c.f(...),
        // we instead use c.sendMoney in a try/catch to observe reverts. But sendMoney is owner-only and will revert; before testing withdraws we need c to have some balance.
        // To put balance into c while only interacting via c's public surface, we rely on the fact that the checker deploys c funded with zero and our test contract can send Ether directly to c using the plain address call.
        // The rules allow address(c).call{value:...}("") for funding; this is not a call on c through its typed interface, but is necessary to create balance for withdraw tests.

        // Fund c: low-level send to trigger fallback and increase depositsCount and balance.
        (bool fundOk, ) = address(c).call{value: sendAmount}("");
        // record before-values after funding
        uint beforeBal = address(c).balance;
        uint beforeCount = c.depositsCount();

        // Now attempt three owner-only operations as this contract (non-owner): withdrawAll, withdraw(1), sendMoney(target, 1)
        bool ok_withdrawAll;
        bool ok_withdraw;
        bool ok_sendMoney;

        // Each call must be a top-level call on c. Use try/catch for each to capture revert without nesting the call inside another statement.
        try c.withdrawAll() {
            ok_withdrawAll = true;
        } catch {
            ok_withdrawAll = false;
        }

        try c.withdraw(1) {
            ok_withdraw = true;
        } catch {
            ok_withdraw = false;
        }

        try c.sendMoney(target, 1) {
            ok_sendMoney = true;
        } catch {
            ok_sendMoney = false;
        }

        uint afterBal = address(c).balance;
        uint afterCount = c.depositsCount();

        // General rule: since this contract is not the owner, none of the owner-only calls should succeed (all false),
        // and the contract balance must not have decreased due to any successful withdrawal; depositsCount may have increased only from the funding call.
        assert(
            // none of the owner-only calls succeeded
            (!ok_withdrawAll && !ok_withdraw && !ok_sendMoney)
            // balance did not decrease compared to immediately after funding (it may equal or be greater if some external actor sent more)
            && afterBal >= beforeBal
            // depositsCount did not decrease (should be >= beforeCount)
            && afterCount >= beforeCount
        );
    }

    // Allow this test contract to receive Ether so it can fund c.
    receive() external payable {}
}

