    // params: callWithdrawAll flag, withdrawAmount, and amountToSend to trigger fallback
    function run(bool callWithdrawAll, uint256 withdrawAmount, uint256 amountToSend) public payable {
        // this test contract is the owner because c was freshly deployed with this as msg.sender
        // Ensure we have funds to send to c
        require(address(this).balance >= amountToSend);

        // Record initial observable state
        uint256 beforeDeposits = c.depositsCount();
        uint256 beforeBalance = address(c).balance;

        // Send Ether to c to trigger fallback which increments depositsCount
        if (amountToSend > 0) {
            (bool s, ) = address(c).call{value: amountToSend}("");
            require(s);
        }

        // Record state after funding
        uint256 fundedDeposits = c.depositsCount();
        uint256 fundedBalance = address(c).balance;

        // Now attempt the owner-only operation but call it via an external call from THIS contract (owner)
        bool ownerCallSucceeded;
        try this.callOwnerOperation(callWithdrawAll, withdrawAmount) {
            ownerCallSucceeded = true;
        } catch {
            ownerCallSucceeded = false;
        }

        // Record state after owner attempt
        uint256 afterOwnerDeposits = c.depositsCount();
        uint256 afterOwnerBalance = address(c).balance;

        // Now simulate a non-owner trying the same operation by performing a low-level call from an address that is not owner.
        // We cannot change msg.sender here, but we can detect the expected behavior: non-owner calls must revert.
        // To emulate a non-owner call, deployer of c made owner==this, so any external call from an EOA other than this would revert.
        // We perform the call via address(c).call to emulate a non-owner (no Solidity-level ownership check bypass).

        bool nonOwnerReverted;
        if (callWithdrawAll) {
            // attempt to call withdrawAll as a non-owner using a low-level call with empty data for function selector
            // prepare selector for withdrawAll()
            bytes memory data = abi.encodeWithSignature("withdrawAll()");
            (bool ok, ) = address(c).call(data);
            nonOwnerReverted = !ok;
        } else {
            bytes memory data = abi.encodeWithSignature("withdraw(uint256)", withdrawAmount);
            (bool ok, ) = address(c).call(data);
            nonOwnerReverted = !ok;
        }

        // Read final observable state
        uint256 finalDeposits = c.depositsCount();
        uint256 finalBalance = address(c).balance;

        // General rule to assert:
        // 1) The owner-call (from this contract) does not decrease depositsCount compared to before funding.
        // 2) If the non-owner attempt reverted then depositsCount and contract balance stayed unchanged by that non-owner attempt
        // Combine into a single assert over observable values and revert flag.
        assert(
            finalDeposits >= beforeDeposits
            && (nonOwnerReverted ? (finalDeposits == afterOwnerDeposits && finalBalance == afterOwnerBalance) : true)
        );
    }

    // helper that calls owner-only functions on c; this contract is the owner
    function callOwnerOperation(bool callWithdrawAll, uint256 withdrawAmount) public {
        if (callWithdrawAll) {
            c.withdrawAll();
        } else {
            c.withdraw(withdrawAmount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
