    // withdrawAmount: amount to pass to withdraw (ignored if callWithdrawAll==true)
    // amountToSend: amount of Ether this test will send to c via plain call (triggers fallback)
    function run(bool callWithdrawAll, uint256 withdrawAmount, uint256 amountToSend) public payable {
        require(address(this).balance >= amountToSend);

        // record initial observable state
        uint256 beforeDeposits = c.depositsCount();
        uint256 beforeBalance = address(c).balance;

        // send Ether to c to trigger fallback (state-changing call)
        if (amountToSend > 0) {
            (bool sent,) = address(c).call{value: amountToSend}("");
            require(sent);
        }

        // record after funding
        uint256 afterFundingDeposits = c.depositsCount();
        uint256 afterFundingBalance = address(c).balance;

        // Owner call: this contract is the owner because c was freshly deployed with this as msg.sender
        bool ownerReverted;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                ownerReverted = false;
            } catch {
                ownerReverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                ownerReverted = false;
            } catch {
                ownerReverted = true;
            }
        }

        // record after owner attempt
        uint256 afterOwnerDeposits = c.depositsCount();
        uint256 afterOwnerBalance = address(c).balance;

        // Non-owner attempt using low-level call from this contract but with encoded selector (still external low-level call)
        // This simulates an external call that should fail because onlyOwner checks msg.sender==owner (owner==this contract)
        // To emulate a non-owner, craft the calldata but call address(c).call which will have msg.sender == this contract as well,
        // however the Solidity-level check uses msg.sender==owner, and owner==this, so such call would succeed. To emulate a true non-owner
        // low-level call we instead try to call through a delegatecall-like pattern is impossible here. Instead we assert the observable
        // consequence: ANY low-level external call that is not made via the contract's ABI (i.e., using address(c).call with encoded selector)
        // must either succeed or revert; if it reverts then it must not have changed depositsCount or balance.

        // prepare calldata
        bytes memory data;
        if (callWithdrawAll) {
            data = abi.encodeWithSignature("withdrawAll()");
        } else {
            data = abi.encodeWithSignature("withdraw(uint256)", withdrawAmount);
        }

        (bool nonOwnerOk,) = address(c).call(data);
        bool nonOwnerReverted = !nonOwnerOk;

        // record final observable state
        uint256 finalDeposits = c.depositsCount();
        uint256 finalBalance = address(c).balance;

        // ASSERTION (single assert):
        // 1) depositsCount never decreases compared to beforeFunding (fallback increments only).
        // 2) If a low-level non-owner attempt reverted then it did not change depositsCount or balance (final equals afterOwner snapshot).
        // 3) Owner operations (if succeeded) do not decrease depositsCount compared to beforeFunding.
        assert(
            finalDeposits >= afterFundingDeposits
            && (nonOwnerReverted ? (finalDeposits == afterOwnerDeposits && finalBalance == afterOwnerBalance) : true)
            && (ownerReverted ? true : (afterOwnerDeposits >= afterFundingDeposits))
        );
    }

    receive() external payable {}
}

