    // The test will (1) record depositsCount and balance, (2) invoke the fallback by sending Ether to c,
    // and (3) optionally call sendMoney to transfer out some Ether and check that only fallback changed depositsCount.
    function run(uint sendToFallbackAmount, address payable target, uint outAmount, bool doSendOut) public payable {
        // Ensure this contract has enough balance to send the requested amounts
        require(address(this).balance >= sendToFallbackAmount + (doSendOut ? outAmount : 0));

