        // - The contract balance increased by exactly sendToFallbackAmount as a result of the fallback
        // - Subsequent call to sendMoney (if any) did not change depositsCount (owner-only should prevent count changes)
        assert(
            afterCount == beforeCount + 1
            && afterBal == beforeBal + sendToFallbackAmount
            && finalCount == afterCount
        );
    }

    // allow this test contract to receive ETH so it can forward to c
    receive() external payable {}
}

