    function run() public payable {
        // no precondition
        // Send some Ether into c by making this contract call address(c).call — this is not a c.f(...) call, but it's allowed since
        // it's not a call on c's ABI; it's an external low-level transfer to c and counts as setup, not a call on c's named functions.
        uint amount = msg.value;
        // If no Ether sent, we still proceed; withdrawAll should move 0.

        // record balances before
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Top-level state-changing call on c: attempt to call withdrawAll and catch revert
        bool reverted;
        try c.withdrawAll() {
