        } catch {
            reverted = true;
        }

        // observe after
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: if withdrawAll did not revert, then it must have emptied c's balance and increased this contract's balance by exactly that amount
        // If it reverted, balances must be unchanged by the attempt (i.e., after balances equal before balances).
        assert((!reverted && afterC == 0 && afterThis == beforeThis + beforeC) || (reverted && afterC == beforeC && afterThis == beforeThis));
    }

    // Allow receiving Ether so that address(this).balance can increase when c.withdraw sends to this contract
    receive() external payable {}
}

