            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Attempt withdrawAll
        try c.withdrawAll{ }() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Attempt sendMoney
        // Ensure this contract has at least sendAmount to forward (but c will send from its balance)
        try c.sendMoney{ }(target, sendAmount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;

        // General rule to assert:
        // - If this contract is the owner, then withdraw/withdrawAll/sendMoney must NOT revert due to permissions (they may revert for other reasons like insufficient balance for transfer). But since owner can call, the permission check won't revert: thus if thisIsOwner is true, then reverted flags correspond only to balance/transfer results; however we can assert that permission-related reverts don't occur, i.e., when caller is owner, the calls do NOT revert solely because msg.sender!=owner. More directly: If thisIsOwner==true then none of the three calls can revert due to onlyOwner — thus they should not revert here (as the contract's code only reverts in onlyOwner or require on call success). For non-owner, the calls must revert due to onlyOwner.
        // Because we cannot inspect revert reasons, we use the observable fact: when thisIsOwner==false all three calls must revert; when thisIsOwner==true they must not revert.

        assert( (thisIsOwner && !withdrewReverted && !withdrewAllReverted && !sendMoneyReverted)
                || (!thisIsOwner && withdrewReverted && withdrewAllReverted && sendMoneyReverted) );
    }

    // Allow this test contract to receive Ether when C sends to it
    receive() external payable { }
}
